 1→//! ECIES key wrapping using secp256k1.
 2→//!
 3→//! Uses the `ecies` Rust crate which is cross-compatible with the `eciesjs` npm package
 4→//! (same author: ecies/rs and ecies/js). Format: ephemeral_pubkey(65) || nonce(16) || tag(16) || ciphertext.
 5→
 6→use thiserror::Error;
 7→
 8→/// secp256k1 uncompressed public key size in bytes (04 prefix + x + y coordinates).
 9→pub const SECP256K1_PUBLIC_KEY_SIZE: usize = 65;
10→
11→/// secp256k1 private key size in bytes.
12→pub const SECP256K1_PRIVATE_KEY_SIZE: usize = 32;
13→
14→/// ECIES minimum ciphertext size: ephemeral pubkey (65) + auth tag (16).
15→pub const ECIES_MIN_CIPHERTEXT_SIZE: usize = SECP256K1_PUBLIC_KEY_SIZE + 16;
16→
17→#[derive(Debug, Error)]
18→pub enum EciesError {
19→    #[error("Key wrapping failed")]
20→    WrappingFailed,
21→    #[error("Key unwrapping failed")]
22→    UnwrappingFailed,
23→    #[error("Invalid public key size")]
24→    InvalidPublicKeySize,
25→    #[error("Invalid public key format")]
26→    InvalidPublicKeyFormat,
27→    #[error("Invalid private key size")]
28→    InvalidPrivateKeySize,
29→}
30→
31→/// Wrap (encrypt) data using ECIES with secp256k1.
32→///
33→/// The `ecies` Rust crate and `eciesjs` npm package produce compatible output.
34→pub fn wrap_key(data: &[u8], recipient_public_key: &[u8]) -> Result<Vec<u8>, EciesError> {
35→    // Validate public key size (uncompressed secp256k1)
36→    if recipient_public_key.len() != SECP256K1_PUBLIC_KEY_SIZE {
37→        return Err(EciesError::InvalidPublicKeySize);
38→    }
39→
40→    // Validate uncompressed public key prefix (0x04)
41→    if recipient_public_key[0] != 0x04 {
42→        return Err(EciesError::InvalidPublicKeyFormat);
43→    }
44→
45→    ecies::encrypt(recipient_public_key, data).map_err(|_| EciesError::WrappingFailed)
46→}
47→
48→/// Unwrap (decrypt) data using ECIES with secp256k1.
49→pub fn unwrap_key(wrapped: &[u8], private_key: &[u8]) -> Result<Vec<u8>, EciesError> {
50→    // Validate private key size
51→    if private_key.len() != SECP256K1_PRIVATE_KEY_SIZE {
52→        return Err(EciesError::InvalidPrivateKeySize);
53→    }
54→
55→    // Validate minimum ciphertext size
56→    if wrapped.len() < ECIES_MIN_CIPHERTEXT_SIZE {
57→        return Err(EciesError::UnwrappingFailed);
58→    }
59→
60→    ecies::decrypt(private_key, wrapped).map_err(|_| EciesError::UnwrappingFailed)
61→}
62→

 1→//! Ed25519 key generation, signing, and verification.
 2→//!
 3→//! Used for IPNS record signing. Deterministic signatures are critical
 4→//! for cross-language test vector verification.
 5→
 6→use ed25519_dalek::{Signer, SigningKey, Verifier, VerifyingKey};
 7→use rand::rngs::OsRng;
 8→use thiserror::Error;
 9→use zeroize::Zeroize;
10→
11→/// Ed25519 public key size in bytes.
12→pub const ED25519_PUBLIC_KEY_SIZE: usize = 32;
13→
14→/// Ed25519 private key size in bytes.
15→pub const ED25519_PRIVATE_KEY_SIZE: usize = 32;
16→
17→/// Ed25519 signature size in bytes.
18→pub const ED25519_SIGNATURE_SIZE: usize = 64;
19→
20→#[derive(Debug, Error)]
21→pub enum Ed25519Error {
22→    #[error("Signing failed")]
23→    SigningFailed,
24→    #[error("Invalid private key size")]
25→    InvalidPrivateKeySize,
26→    #[error("Invalid public key")]
27→    InvalidPublicKey,
28→}
29→
30→/// Generate a new Ed25519 keypair.
31→///
32→/// Returns (public_key_32bytes, private_key_32bytes).
33→pub fn generate_ed25519_keypair() -> (Vec<u8>, Vec<u8>) {
34→    let signing_key = SigningKey::generate(&mut OsRng);
35→    let verifying_key = signing_key.verifying_key();
36→
37→    (
38→        verifying_key.to_bytes().to_vec(),
39→        signing_key.to_bytes().to_vec(),
40→    )
41→}
42→
43→/// Sign a message with an Ed25519 private key.
44→///
45→/// Returns 64-byte deterministic signature.
46→pub fn sign_ed25519(message: &[u8], private_key: &[u8]) -> Result<Vec<u8>, Ed25519Error> {
47→    if private_key.len() != ED25519_PRIVATE_KEY_SIZE {
48→        return Err(Ed25519Error::InvalidPrivateKeySize);
49→    }
50→
51→    let mut key_bytes: [u8; 32] = private_key
52→        .try_into()
53→        .map_err(|_| Ed25519Error::InvalidPrivateKeySize)?;
54→    let signing_key = SigningKey::from_bytes(&key_bytes);
55→    key_bytes.zeroize();
56→    let signature = signing_key.sign(message);
57→
58→    Ok(signature.to_bytes().to_vec())
59→}
60→
61→/// Verify an Ed25519 signature.
62→///
63→/// Returns true if valid, false otherwise. Never throws.
64→pub fn verify_ed25519(message: &[u8], signature: &[u8], public_key: &[u8]) -> bool {
65→    if signature.len() != ED25519_SIGNATURE_SIZE || public_key.len() != ED25519_PUBLIC_KEY_SIZE {
66→        return false;
67→    }
68→
69→    let Ok(sig_bytes) = <[u8; 64]>::try_from(signature) else {
70→        return false;
71→    };
72→    let Ok(key_bytes) = <[u8; 32]>::try_from(public_key) else {
73→        return false;
74→    };
75→
76→    let Ok(verifying_key) = VerifyingKey::from_bytes(&key_bytes) else {
77→        return false;
78→    };
79→
80→    let sig = ed25519_dalek::Signature::from_bytes(&sig_bytes);
81→    verifying_key.verify(message, &sig).is_ok()
82→}
83→
84→/// Derive the 32-byte public key from a 32-byte Ed25519 private key.
85→pub fn get_public_key(private_key: &[u8]) -> Result<Vec<u8>, Ed25519Error> {
86→    if private_key.len() != ED25519_PRIVATE_KEY_SIZE {
87→        return Err(Ed25519Error::InvalidPrivateKeySize);
88→    }
89→
90→    let mut key_bytes: [u8; 32] = private_key
91→        .try_into()
92→        .map_err(|_| Ed25519Error::InvalidPrivateKeySize)?;
93→    let signing_key = SigningKey::from_bytes(&key_bytes);
94→    key_bytes.zeroize();
95→    let verifying_key = signing_key.verifying_key();
96→
97→    Ok(verifying_key.to_bytes().to_vec())
98→}
99→

  1→//! IPNS record creation, marshaling, and name derivation.
  2→//!
  3→//! Produces IPNS records compatible with the TypeScript `ipns` npm package output.
  4→//! - CBOR-encoded data field with V2 signature
  5→//! - Protobuf-encoded IpnsEntry for marshaling
  6→//! - CIDv1 base36 IPNS name derivation
  7→
  8→use std::time::{Duration, SystemTime, UNIX_EPOCH};
  9→
 10→use ciborium::Value as CborValue;
 11→use thiserror::Error;
 12→
 13→use super::ed25519::{get_public_key, sign_ed25519};
 14→
 15→/// IPNS signature prefix per IPFS spec: "ipns-signature:".
 16→const IPNS_SIGNATURE_PREFIX: &[u8] = b"ipns-signature:";
 17→
 18→/// Default IPNS record TTL: 300 seconds (5 minutes) in nanoseconds.
 19→/// This matches the ipns npm package default.
 20→const DEFAULT_TTL_NS: u64 = 300_000_000_000;
 21→
 22→#[derive(Debug, Error)]
 23→pub enum IpnsError {
 24→    #[error("IPNS record creation failed")]
 25→    CreationFailed,
 26→    #[error("IPNS record marshaling failed")]
 27→    MarshalingFailed,
 28→    #[error("IPNS name derivation failed")]
 29→    DerivationFailed,
 30→    #[error("Invalid private key")]
 31→    InvalidPrivateKey,
 32→    #[error("Invalid public key")]
 33→    InvalidPublicKey,
 34→    #[error("CBOR encoding failed")]
 35→    CborEncodingFailed,
 36→    #[error("Signing failed")]
 37→    SigningFailed,
 38→}
 39→
 40→/// IPNS record structure matching the TypeScript IPNSRecord type.
 41→#[derive(Debug, Clone)]
 42→pub struct IpnsRecord {
 43→    /// IPFS path value (e.g., "/ipfs/bafy...").
 44→    pub value: String,
 45→    /// RFC3339 validity timestamp with nanosecond precision.
 46→    pub validity: String,
 47→    /// Validity type (0 = EOL).
 48→    pub validity_type: u32,
 49→    /// Monotonically increasing sequence number.
 50→    pub sequence: u64,
 51→    /// TTL in nanoseconds.
 52→    pub ttl: u64,
 53→    /// 64-byte Ed25519 V1 signature.
 54→    pub signature_v1: Vec<u8>,
 55→    /// 64-byte Ed25519 V2 signature.
 56→    pub signature_v2: Vec<u8>,
 57→    /// CBOR-encoded record data.
 58→    pub data: Vec<u8>,
 59→    /// 32-byte Ed25519 public key.
 60→    pub public_key: Vec<u8>,
 61→}
 62→
 63→/// Build the CBOR-encoded data field for an IPNS record.
 64→///
 65→/// The field order matches the ipns npm package: TTL, Value, Sequence, Validity, ValidityType.
 66→/// Keys are strings, values match the types used by the ipns package.
 67→fn build_cbor_data(
 68→    value: &str,
 69→    validity: &str,
 70→    sequence: u64,
 71→    ttl: u64,
 72→) -> Result<Vec<u8>, IpnsError> {
 73→    // The ipns npm package uses a CBOR map with string keys.
 74→    // Field order (matching ipns npm package output): TTL, Value, Sequence, Validity, ValidityType
 75→    //
 76→    // - TTL: unsigned integer (nanoseconds)
 77→    // - Value: byte string (the IPFS path as bytes)
 78→    // - Sequence: unsigned integer
 79→    // - Validity: byte string (RFC3339 timestamp as bytes)
 80→    // - ValidityType: unsigned integer (0 = EOL)
 81→    let cbor_map = CborValue::Map(vec![
 82→        (
 83→            CborValue::Text("TTL".to_string()),
 84→            CborValue::Integer(ttl.into()),
 85→        ),
 86→        (
 87→            CborValue::Text("Value".to_string()),
 88→            CborValue::Bytes(value.as_bytes().to_vec()),
 89→        ),
 90→        (
 91→            CborValue::Text("Sequence".to_string()),
 92→            CborValue::Integer(sequence.into()),
 93→        ),
 94→        (
 95→            CborValue::Text("Validity".to_string()),
 96→            CborValue::Bytes(validity.as_bytes().to_vec()),
 97→        ),
 98→        (
 99→            CborValue::Text("ValidityType".to_string()),
100→            CborValue::Integer(0.into()),
101→        ),
102→    ]);
103→
104→    let mut buf = Vec::new();
105→    ciborium::into_writer(&cbor_map, &mut buf).map_err(|_| IpnsError::CborEncodingFailed)?;
106→    Ok(buf)
107→}
108→
109→/// Format a timestamp as RFC3339 with nanosecond precision matching the ipns npm package.
110→///
111→/// The ipns package uses format: "2026-02-08T23:31:12.138000000Z"
112→/// This is: full datetime + "." + 9-digit nanoseconds + "Z"
113→fn format_validity_timestamp(validity_time: SystemTime) -> String {
114→    let duration = validity_time
115→        .duration_since(UNIX_EPOCH)
116→        .unwrap_or(Duration::ZERO);
117→    let secs = duration.as_secs();
118→    let nanos = duration.subsec_nanos();
119→
120→    // Compute date/time components from Unix timestamp
121→    let days = secs / 86400;
122→    let time_of_day = secs % 86400;
123→    let hours = time_of_day / 3600;
124→    let minutes = (time_of_day % 3600) / 60;
125→    let seconds = time_of_day % 60;
126→
127→    // Convert days since epoch to date using civil_from_days algorithm
128→    let (year, month, day) = civil_from_days(days as i64);
129→
130→    format!(
131→        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:09}Z",
132→        year, month, day, hours, minutes, seconds, nanos
133→    )
134→}
135→
136→/// Convert days since Unix epoch to (year, month, day).
137→/// Algorithm from Howard Hinnant's civil_from_days.
138→fn civil_from_days(days: i64) -> (i64, u32, u32) {
139→    let z = days + 719468;
140→    let era = if z >= 0 { z } else { z - 146096 } / 146097;
141→    let doe = (z - era * 146097) as u64; // day of era [0, 146096]
142→    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365; // year of era [0, 399]
143→    let y = (yoe as i64) + era * 400;
144→    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // day of year [0, 365]
145→    let mp = (5 * doy + 2) / 153; // [0, 11]
146→    let d = doy - (153 * mp + 2) / 5 + 1; // day [1, 31]
147→    let m = if mp < 10 { mp + 3 } else { mp - 9 }; // month [1, 12]
148→    let y = if m <= 2 { y + 1 } else { y };
149→    (y, m as u32, d as u32)
150→}
151→
152→/// Compute the V1 signature.
153→///
154→/// Per IPNS spec, V1 signature is over: value_bytes + validity_bytes + varint(validityType)
155→fn compute_v1_signature(
156→    ed25519_private_key: &[u8; 32],
157→    value: &str,
158→    validity: &str,
159→) -> Result<Vec<u8>, IpnsError> {
160→    let mut data_to_sign = Vec::new();
161→    data_to_sign.extend_from_slice(value.as_bytes());
162→    data_to_sign.extend_from_slice(validity.as_bytes());
163→    // ValidityType 0 as varint = single byte 0x00
164→    data_to_sign.push(0x00);
165→
166→    sign_ed25519(&data_to_sign, ed25519_private_key).map_err(|_| IpnsError::SigningFailed)
167→}
168→
169→/// Compute the V2 signature.
170→///
171→/// Per IPNS spec, V2 signature is over: "ipns-signature:" + cbor_data
172→fn compute_v2_signature(
173→    ed25519_private_key: &[u8; 32],
174→    cbor_data: &[u8],
175→) -> Result<Vec<u8>, IpnsError> {
176→    let mut data_to_sign = Vec::with_capacity(IPNS_SIGNATURE_PREFIX.len() + cbor_data.len());
177→    data_to_sign.extend_from_slice(IPNS_SIGNATURE_PREFIX);
178→    data_to_sign.extend_from_slice(cbor_data);
179→
180→    sign_ed25519(&data_to_sign, ed25519_private_key).map_err(|_| IpnsError::SigningFailed)
181→}
