  1→//! Vault key blob v2 format: binary envelope for ECIES-wrapped rootFolderKey.
  2→//!
  3→//! Format: 0x02 | uint16_BE(key_len) | ECIES_encrypted_key
  4→//!
  5→//! This is a key-only blob — folder metadata is stored separately at
  6→//! the root folder's own IPNS name using standard v1 JSON format.
  7→
  8→/// Version byte for v2 format.
  9→pub const BLOB_V2_VERSION: u8 = 0x02;
 10→
 11→/// Detect whether a vault blob is v1 (JSON) or v2 (binary envelope).
 12→///
 13→/// v1 blobs start with 0x7B ('{' -- JSON). v2 blobs start with 0x02.
 14→pub fn detect_blob_version(blob: &[u8]) -> u8 {
 15→    if !blob.is_empty() && blob[0] == BLOB_V2_VERSION {
 16→        2
 17→    } else {
 18→        1
 19→    }
 20→}
 21→
 22→/// Serialize a vault key blob v2.
 23→///
 24→/// Produces: `0x02 | uint16_BE(key_len) | encrypted_root_folder_key`
 25→pub fn serialize_vault_blob_v2(encrypted_root_folder_key: &[u8]) -> Result<Vec<u8>, String> {
 26→    if encrypted_root_folder_key.is_empty() {
 27→        return Err("Encrypted key must not be empty for v2 blob".into());
 28→    }
 29→    if encrypted_root_folder_key.len() > u16::MAX as usize {
 30→        return Err(format!(
 31→            "Encrypted key too long for v2 blob ({} bytes, max {})",
 32→            encrypted_root_folder_key.len(),
 33→            u16::MAX
 34→        ));
 35→    }
 36→    let key_len = encrypted_root_folder_key.len() as u16;
 37→    let mut result = Vec::with_capacity(3 + encrypted_root_folder_key.len());
 38→    result.push(BLOB_V2_VERSION);
 39→    result.push((key_len >> 8) as u8);
 40→    result.push((key_len & 0xff) as u8);
 41→    result.extend_from_slice(encrypted_root_folder_key);
 42→    Ok(result)
 43→}
 44→
 45→/// Deserialize a vault key blob v2 to extract the encrypted rootFolderKey.
 46→///
 47→/// Returns borrowed slice into the original blob for zero-copy parsing.
 48→pub fn deserialize_vault_blob_v2(blob: &[u8]) -> Result<&[u8], String> {
 49→    if blob.len() < 3 {
 50→        return Err(format!(
 51→            "Vault blob too short for v2 header (need at least 3 bytes, have {})",
 52→            blob.len()
 53→        ));
 54→    }
 55→    if blob[0] != BLOB_V2_VERSION {
 56→        return Err("Not a v2 vault blob".into());
 57→    }
 58→    let key_len = ((blob[1] as usize) << 8) | (blob[2] as usize);
 59→    if key_len == 0 {
 60→        return Err("Invalid v2 blob: encrypted key length must be > 0".into());
 61→    }
 62→    if blob.len() < 3 + key_len {
 63→        return Err(format!(
 64→            "Vault blob too short for key (expected {} bytes, have {})",
 65→            key_len,
 66→            blob.len() - 3
 67→        ));
 68→    }
 69→    Ok(&blob[3..3 + key_len])
 70→}
