 704→#[test]
 705→fn ipns_record_signature_v2_is_deterministic_for_same_cbor() {
 706→    // Since the CBOR data includes a timestamp, the signature will differ
 707→    // between calls. But for the SAME CBOR data, the signature must be deterministic.
 708→    let private_key = hex::decode(ED25519_TEST_PRIVATE_KEY).unwrap();
 709→    let pk: [u8; 32] = private_key.clone().try_into().unwrap();
 710→
 711→    let record = ipns::create_ipns_record(&pk, "/ipfs/bafy123", 1, 86400000).unwrap();
 712→
 713→    // Re-sign the same CBOR data manually to verify determinism
 714→    let prefix = b"ipns-signature:";
 715→    let mut data_to_sign = Vec::new();
 716→    data_to_sign.extend_from_slice(prefix);
 717→    data_to_sign.extend_from_slice(&record.data);
 718→
 719→    let sig = ed25519::sign_ed25519(&data_to_sign, &private_key).unwrap();
 720→    assert_eq!(
 721→        sig, record.signature_v2,
 722→        "V2 signature must be deterministic"
 723→    );
 724→}
