 727→fn ipns_record_cbor_data_contains_expected_fields() {
 728→    let private_key = hex::decode(ED25519_TEST_PRIVATE_KEY).unwrap();
 729→    let pk: [u8; 32] = private_key.try_into().unwrap();
 730→    let value = "/ipfs/REDACTED";
 731→
 732→    let record = ipns::create_ipns_record(&pk, value, 42, 86400000).unwrap();
 733→
 734→    // The CBOR data should decode to a map with TTL, Value, Sequence, Validity, ValidityType
 735→    let cbor_value: ciborium::Value =
 736→        ciborium::from_reader(std::io::Cursor::new(&record.data)).unwrap();
 737→
 738→    if let ciborium::Value::Map(entries) = cbor_value {
 739→        assert_eq!(entries.len(), 5, "CBOR map should have 5 fields");
 740→
 741→        // Check field names exist
 742→        let keys: Vec<String> = entries
 743→            .iter()
 744→            .filter_map(|(k, _)| {
 745→                if let ciborium::Value::Text(s) = k {
 746→                    Some(s.clone())
 747→                } else {
 748→                    None
 749→                }
 750→            })
 751→            .collect();
 752→
 753→        assert!(keys.contains(&"TTL".to_string()));
 754→        assert!(keys.contains(&"Value".to_string()));
 755→        assert!(keys.contains(&"Sequence".to_string()));
 756→        assert!(keys.contains(&"Validity".to_string()));
 757→        assert!(keys.contains(&"ValidityType".to_string()));
 758→    } else {
 759→        panic!("CBOR data should be a map");
 760→    }
 761→}
