//! AES-256-GCM encryption/decryption.
//!
//! Sealed format: IV (12 bytes) || Ciphertext || Auth Tag (16 bytes)
//! This matches the TypeScript `sealAesGcm` output exactly.

use aes_gcm::{
    aead::{Aead, KeyInit},
    Aes256Gcm, Nonce,
};

use crate::error::CryptoError;
use crate::utils::generate_iv;

/// AES-256-GCM key size in bytes (256 bits).
pub const AES_KEY_SIZE: usize = 32;

/// AES-GCM IV size in bytes (96 bits).
pub const AES_IV_SIZE: usize = 12;

/// AES-GCM authentication tag size in bytes (128 bits).
pub const AES_TAG_SIZE: usize = 16;

/// Minimum sealed data size: IV + auth tag (empty plaintext).
const MIN_SEALED_SIZE: usize = AES_IV_SIZE + AES_TAG_SIZE;

/// Encrypt data using AES-256-GCM.
///
/// Returns ciphertext with 16-byte auth tag appended (same as Web Crypto API).
pub fn encrypt_aes_gcm(
    plaintext: &[u8],
    key: &[u8; 32],
    iv: &[u8; 12],
) -> Result<Vec<u8>, CryptoError> {
    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| CryptoError::AesEncryptionFailed)?;
    let nonce = Nonce::from_slice(iv);

    cipher
        .encrypt(nonce, plaintext)
        .map_err(|_| CryptoError::AesEncryptionFailed)
}

/// Decrypt data using AES-256-GCM.
///
/// Expects ciphertext with 16-byte auth tag appended.
pub fn decrypt_aes_gcm(
    ciphertext: &[u8],
    key: &[u8; 32],
    iv: &[u8; 12],
) -> Result<Vec<u8>, CryptoError> {
    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| CryptoError::AesDecryptionFailed)?;
    let nonce = Nonce::from_slice(iv);

    cipher
        .decrypt(nonce, ciphertext)
        .map_err(|_| CryptoError::AesDecryptionFailed)
}

/// Seal data using AES-256-GCM with automatic IV generation.
///
/// Returns: IV (12 bytes) || Ciphertext || Auth Tag (16 bytes)
/// This format matches the TypeScript `sealAesGcm` exactly.
pub fn seal_aes_gcm(plaintext: &[u8], key: &[u8; 32]) -> Result<Vec<u8>, CryptoError> {
    let iv = generate_iv();
    let ciphertext = encrypt_aes_gcm(plaintext, key, &iv)?;

    // IV || ciphertext (which already includes the tag)
    let mut sealed = Vec::with_capacity(AES_IV_SIZE + ciphertext.len());
    sealed.extend_from_slice(&iv);
    sealed.extend_from_slice(&ciphertext);
    Ok(sealed)
}

/// Unseal data encrypted with `seal_aes_gcm`.
///
/// Extracts IV from first 12 bytes, decrypts remainder.
pub fn unseal_aes_gcm(sealed: &[u8], key: &[u8; 32]) -> Result<Vec<u8>, CryptoError> {
    if sealed.len() < MIN_SEALED_SIZE {
        return Err(CryptoError::AesDecryptionFailed);
    }

    let iv: [u8; 12] = sealed[..AES_IV_SIZE]
        .try_into()
        .map_err(|_| CryptoError::AesDecryptionFailed)?;
    let ciphertext = &sealed[AES_IV_SIZE..];

    decrypt_aes_gcm(ciphertext, key, &iv)
}

//! AES-256-CTR encryption/decryption.
//!
//! Symmetric encryption for media file content using CTR mode.
//! CTR mode enables random-access decryption (any byte range without
//! processing preceding bytes), required for streaming media playback.
//!
//! Uses Ctr64BE (big-endian 64-bit counter) to match Web Crypto API's
//! `AES-CTR` with `length: 64`.
//!
//! SECURITY NOTE: AES-CTR does NOT provide authentication (unlike GCM).
//! Integrity is provided by IPFS content addressing.

use aes::Aes256;
use ctr::cipher::{KeyIvInit, StreamCipher};

use crate::error::CryptoError;

/// AES-CTR IV size in bytes (128-bit counter block).
pub const AES_CTR_IV_SIZE: usize = 16;

/// AES block size in bytes.
const AES_BLOCK_SIZE: usize = 16;

/// Type alias for AES-256-CTR with 64-bit big-endian counter.
/// Matches Web Crypto API's `AES-CTR` with `length: 64`.
type Aes256Ctr64BE = ctr::Ctr64BE<Aes256>;

/// Encrypt data using AES-256-CTR.
///
/// Each encryption MUST use a unique IV (nonce + counter) with the same key.
/// Reusing nonce+key pairs is catastrophic for AES-CTR security.
///
/// CTR output is the same size as the input (no authentication tag).
pub fn encrypt_aes_ctr(
    plaintext: &[u8],
    key: &[u8; 32],
    iv: &[u8; 16],
) -> Result<Vec<u8>, CryptoError> {
    let mut cipher =
        Aes256Ctr64BE::new(key.into(), iv.into());

    let mut output = plaintext.to_vec();
    cipher.apply_keystream(&mut output);

    Ok(output)
}

/// Decrypt data encrypted with AES-256-CTR.
///
/// CTR encrypt == decrypt (XOR is symmetric), but provided as a separate
/// function for API clarity.
pub fn decrypt_aes_ctr(
    ciphertext: &[u8],
    key: &[u8; 32],
    iv: &[u8; 16],
) -> Result<Vec<u8>, CryptoError> {
    // CTR mode: decrypt is identical to encrypt
    encrypt_aes_ctr(ciphertext, key, iv)
}

/// Decrypt an arbitrary byte range from AES-256-CTR encrypted data.
///
/// Computes the correct counter value for any byte offset and decrypts
/// only the required blocks, avoiding the need to process the entire file.
///
/// The counter is computed as: baseCounter + floor(startByte / 16)
/// where baseCounter is the initial counter value from the IV (bytes 8-15).
///
/// `ciphertext` must contain at least the block-aligned range covering
/// `[start_byte, end_byte]` (inclusive).
pub fn decrypt_aes_ctr_range(
    ciphertext: &[u8],
    key: &[u8; 32],
    iv: &[u8; 16],
    start_byte: usize,
    end_byte: usize,
) -> Result<Vec<u8>, CryptoError> {
    if start_byte > end_byte {
        return Err(CryptoError::InvalidRange);
    }

    if ciphertext.is_empty() || start_byte >= ciphertext.len() {
        return Ok(Vec::new());
    }

    // Clamp end_byte to actual data
    let clamped_end = end_byte.min(ciphertext.len().saturating_sub(1));
    if clamped_end < start_byte {
        // Range is entirely beyond available data
        return Ok(Vec::new());
    }

    // Compute block-aligned range
    let start_block = start_byte / AES_BLOCK_SIZE;
    let end_block = clamped_end / AES_BLOCK_SIZE;
    let block_aligned_start = start_block * AES_BLOCK_SIZE;
    let block_aligned_end = ((end_block + 1) * AES_BLOCK_SIZE).min(ciphertext.len());

    // Build counter for starting block:
    // Copy nonce (first 8 bytes of IV), compute counter = baseCounter + startBlock
    let mut counter = [0u8; 16];
    counter[..8].copy_from_slice(&iv[..8]);

    let base_counter = u64::from_be_bytes(iv[8..16].try_into().unwrap());
    let new_counter = base_counter.wrapping_add(start_block as u64);
    counter[8..16].copy_from_slice(&new_counter.to_be_bytes());

    // Create cipher with adjusted counter
    let mut cipher = Aes256Ctr64BE::new(key.into(), &counter.into());

    // Decrypt the block-aligned range
    let mut decrypted = ciphertext[block_aligned_start..block_aligned_end].to_vec();
    cipher.apply_keystream(&mut decrypted);

    // Extract exact requested bytes from decrypted block-aligned data
    let offset_in_first_block = start_byte - block_aligned_start;
    let requested_length = clamped_end - start_byte + 1;
    let result = decrypted[offset_in_first_block..offset_in_first_block + requested_length].to_vec();

    Ok(result)
}

//! ECIES key wrapping using secp256k1.
//!
//! Uses the `ecies` Rust crate which is cross-compatible with the `eciesjs` npm package
//! (same author: ecies/rs and ecies/js). Format: ephemeral_pubkey(65) || nonce(16) || tag(16) || ciphertext.

use crate::error::CryptoError;

/// secp256k1 uncompressed public key size in bytes (04 prefix + x + y coordinates).
pub const SECP256K1_PUBLIC_KEY_SIZE: usize = 65;

/// secp256k1 private key size in bytes.
pub const SECP256K1_PRIVATE_KEY_SIZE: usize = 32;

/// ECIES minimum ciphertext size: ephemeral pubkey (65) + auth tag (16).
pub const ECIES_MIN_CIPHERTEXT_SIZE: usize = SECP256K1_PUBLIC_KEY_SIZE + 16;

/// Wrap (encrypt) data using ECIES with secp256k1.
///
/// The `ecies` Rust crate and `eciesjs` npm package produce compatible output.
pub fn wrap_key(data: &[u8], recipient_public_key: &[u8]) -> Result<Vec<u8>, CryptoError> {
    // Validate public key size (uncompressed secp256k1)
    if recipient_public_key.len() != SECP256K1_PUBLIC_KEY_SIZE {
        return Err(CryptoError::InvalidPublicKey);
    }

    // Validate uncompressed public key prefix (0x04)
    if recipient_public_key[0] != 0x04 {
        return Err(CryptoError::InvalidPublicKey);
    }

    ecies::encrypt(recipient_public_key, data).map_err(|_| CryptoError::EciesWrappingFailed)
}

/// Unwrap (decrypt) data using ECIES with secp256k1.
pub fn unwrap_key(wrapped: &[u8], private_key: &[u8]) -> Result<Vec<u8>, CryptoError> {
    // Validate private key size
    if private_key.len() != SECP256K1_PRIVATE_KEY_SIZE {
        return Err(CryptoError::InvalidPrivateKey);
    }

    // Validate minimum ciphertext size
    if wrapped.len() < ECIES_MIN_CIPHERTEXT_SIZE {
        return Err(CryptoError::EciesUnwrappingFailed);
    }

    ecies::decrypt(private_key, wrapped).map_err(|_| CryptoError::EciesUnwrappingFailed)
}

//! Ed25519 key generation, signing, and verification.
//!
//! Used for IPNS record signing. Deterministic signatures are critical
//! for cross-language test vector verification.

use ed25519_dalek::{Signer, SigningKey, Verifier, VerifyingKey};
use rand::rngs::OsRng;
use zeroize::Zeroize;

use crate::error::CryptoError;

/// Ed25519 public key size in bytes.
pub const ED25519_PUBLIC_KEY_SIZE: usize = 32;

/// Ed25519 private key size in bytes.
pub const ED25519_PRIVATE_KEY_SIZE: usize = 32;

/// Ed25519 signature size in bytes.
pub const ED25519_SIGNATURE_SIZE: usize = 64;

/// Generate a new Ed25519 keypair.
///
/// Returns (public_key_32bytes, private_key_32bytes).
pub fn generate_ed25519_keypair() -> (Vec<u8>, Vec<u8>) {
    let signing_key = SigningKey::generate(&mut OsRng);
    let verifying_key = signing_key.verifying_key();

    (
        verifying_key.to_bytes().to_vec(),
        signing_key.to_bytes().to_vec(),
    )
}

/// Sign a message with an Ed25519 private key.
///
/// Returns 64-byte deterministic signature.
pub fn sign_ed25519(message: &[u8], private_key: &[u8]) -> Result<Vec<u8>, CryptoError> {
    if private_key.len() != ED25519_PRIVATE_KEY_SIZE {
        return Err(CryptoError::InvalidPrivateKey);
    }

    let mut key_bytes: [u8; 32] = private_key
        .try_into()
        .map_err(|_| CryptoError::InvalidPrivateKey)?;
    let signing_key = SigningKey::from_bytes(&key_bytes);
    key_bytes.zeroize();
    let signature = signing_key.sign(message);

    Ok(signature.to_bytes().to_vec())
}

/// Verify an Ed25519 signature.
///
/// Returns true if valid, false otherwise. Never throws.
pub fn verify_ed25519(message: &[u8], signature: &[u8], public_key: &[u8]) -> bool {
    if signature.len() != ED25519_SIGNATURE_SIZE || public_key.len() != ED25519_PUBLIC_KEY_SIZE {
        return false;
    }

    let Ok(sig_bytes) = <[u8; 64]>::try_from(signature) else {
        return false;
    };
    let Ok(key_bytes) = <[u8; 32]>::try_from(public_key) else {
        return false;
    };

    let Ok(verifying_key) = VerifyingKey::from_bytes(&key_bytes) else {
        return false;
    };

    let sig = ed25519_dalek::Signature::from_bytes(&sig_bytes);
    verifying_key.verify(message, &sig).is_ok()
}

/// Derive the 32-byte public key from a 32-byte Ed25519 private key.
pub fn get_public_key(private_key: &[u8]) -> Result<Vec<u8>, CryptoError> {
    if private_key.len() != ED25519_PRIVATE_KEY_SIZE {
        return Err(CryptoError::InvalidPrivateKey);
    }

    let mut key_bytes: [u8; 32] = private_key
        .try_into()
        .map_err(|_| CryptoError::InvalidPrivateKey)?;
    let signing_key = SigningKey::from_bytes(&key_bytes);
    key_bytes.zeroize();
    let verifying_key = signing_key.verifying_key();

    Ok(verifying_key.to_bytes().to_vec())
}

//! IPNS name derivation (CIDv1 base36 from Ed25519 public key).
//!
//! This module extracts only the pure IPNS name derivation logic.
//! IPNS record creation/marshaling stays in the desktop app (or cipherbox-core)
//! because it involves domain-specific types and CBOR/protobuf encoding.

use crate::error::CryptoError;

/// Encode the Ed25519 public key in libp2p PublicKey protobuf format.
///
/// message PublicKey { KeyType Type = 1; bytes Data = 2; }
/// where KeyType.Ed25519 = 1
pub fn encode_libp2p_public_key(ed25519_public_key: &[u8]) -> Vec<u8> {
    let mut buf = Vec::new();
    // Field 1 (Type): varint, field_number=1, wire_type=0 => tag = 0x08
    buf.push(0x08);
    // Value: 1 (Ed25519)
    buf.push(0x01);
    // Field 2 (Data): length-delimited, field_number=2, wire_type=2 => tag = 0x12
    buf.push(0x12);
    // Length of public key (32 bytes)
    buf.push(ed25519_public_key.len() as u8);
    buf.extend_from_slice(ed25519_public_key);
    buf
}

/// Derive the IPNS name (CIDv1 base36) from an Ed25519 public key.
///
/// Steps:
/// 1. Wrap public key in libp2p PublicKey protobuf
/// 2. Create identity multihash: 0x00 (identity) + varint(len) + data
/// 3. Create CIDv1: version=1, codec=0x72 (libp2p-key), multihash
/// 4. Encode as base36 (k... prefix)
pub fn derive_ipns_name(ed25519_public_key: &[u8; 32]) -> Result<String, CryptoError> {
    // Step 1: Wrap in libp2p PublicKey protobuf
    let libp2p_pub_key = encode_libp2p_public_key(ed25519_public_key);

    // Step 2: Create identity multihash
    // Identity multihash: code=0x00, length=varint(data.len()), data
    let mut identity_multihash = Vec::new();
    identity_multihash.push(0x00); // identity hash function code
    // Encode length as unsigned varint
    encode_unsigned_varint(&mut identity_multihash, libp2p_pub_key.len() as u64);
    identity_multihash.extend_from_slice(&libp2p_pub_key);

    // Step 3: Create CIDv1
    // CIDv1 binary: version(1) + codec(0x72, libp2p-key) + multihash
    let mut cid_bytes = Vec::new();
    encode_unsigned_varint(&mut cid_bytes, 1); // CID version 1
    encode_unsigned_varint(&mut cid_bytes, 0x72); // libp2p-key codec
    cid_bytes.extend_from_slice(&identity_multihash);

    // Step 4: Encode as base36 with 'k' prefix
    let base36 = encode_base36(&cid_bytes);
    Ok(format!("k{}", base36))
}

/// Encode unsigned varint (same as protobuf varint / LEB128).
fn encode_unsigned_varint(buf: &mut Vec<u8>, mut value: u64) {
    loop {
        let byte = (value & 0x7f) as u8;
        value >>= 7;
        if value == 0 {
            buf.push(byte);
            break;
        } else {
            buf.push(byte | 0x80);
        }
    }
}

/// Encode bytes as base36 (lowercase).
///
/// Base36 alphabet: REDACTED
fn encode_base36(data: &[u8]) -> String {
    if data.is_empty() {
        return String::new();
    }

    const ALPHABET: &[u8; 36] = b"REDACTED";

    // Count leading zeros
    let leading_zeros = data.iter().take_while(|&&b| b == 0).count();

    // Convert byte array to big integer using repeated division
    let mut num = data.to_vec();
    let mut result = Vec::new();

    while !num.is_empty() {
        let mut remainder: u32 = 0;
        let mut quotient = Vec::new();

        for &byte in &num {
            let acc = (remainder << 8) | (byte as u32);
            let digit = acc / 36;
            remainder = acc % 36;

            if !quotient.is_empty() || digit > 0 {
                quotient.push(digit as u8);
            }
        }

        result.push(ALPHABET[remainder as usize]);
        num = quotient;
    }

    // Add leading '0's for each leading zero byte
    for _ in 0..leading_zeros {
        result.push(b'0');
    }

    result.reverse();
    String::from_utf8(result).unwrap_or_default()
}

//! HKDF-SHA256 deterministic IPNS keypair derivation.
//!
//! Derives deterministic Ed25519 IPNS keypairs from a secp256k1 private key
//! using HKDF-SHA256 with domain-separated info strings. Matches the TypeScript
//! implementations in `@cipherbox/crypto` (vault/derive-ipns.ts, file/derive-ipns.ts,
//! registry/derive-ipns.ts).
//!
//! Derivation path:
//!   secp256k1 privateKey (32 bytes)
//!     -> HKDF-SHA256(salt="CipherBox-v1", info=<domain-specific>)
//!     -> 32-byte Ed25519 seed
//!     -> Ed25519 keypair
//!     -> IPNS name (k51...)

use ed25519_dalek::SigningKey;
use hkdf::Hkdf;
use sha2::Sha256;
use zeroize::{Zeroize, Zeroizing};

use crate::error::CryptoError;
use crate::ipns_name;

/// Common HKDF salt for all CipherBox derivations.
const HKDF_SALT: &[u8] = b"CipherBox-v1";

/// HKDF info for vault IPNS keypair derivation (root folder metadata).
const VAULT_HKDF_INFO: &[u8] = b"cipherbox-vault-ipns-v1";

/// HKDF info for vault key blob IPNS keypair derivation (rootFolderKey storage).
const VAULT_KEY_HKDF_INFO: &[u8] = b"cipherbox-vault-key-ipns-v1";

/// HKDF info for device registry IPNS keypair derivation.
const REGISTRY_HKDF_INFO: &[u8] = b"cipherbox-device-registry-ipns-v1";

/// HKDF info for recycle bin IPNS keypair derivation.
const BIN_HKDF_INFO: &[u8] = b"cipherbox-recycle-bin-ipns-v1";

/// HKDF info prefix for per-file IPNS keypair derivation.
const FILE_HKDF_INFO_PREFIX: &str = "cipherbox-file-ipns-v1:";

/// Minimum file ID length (matches TypeScript validation).
const MIN_FILE_ID_LENGTH: usize = 10;

/// Internal helper: derive an Ed25519 keypair and IPNS name from HKDF output.
///
/// All three public functions follow the same pattern and delegate here.
fn derive_ipns_keypair(
    user_private_key: &[u8; 32],
    info: &[u8],
) -> Result<(Zeroizing<Vec<u8>>, Vec<u8>, String), CryptoError> {
    // 1. HKDF-SHA256: extract + expand
    let hk = Hkdf::<Sha256>::new(Some(HKDF_SALT), user_private_key);
    let mut okm = [0u8; 32];
    hk.expand(info, &mut okm)
        .map_err(|_| CryptoError::HkdfDerivationFailed)?;

    // 2. Ed25519 keypair from 32-byte seed
    let signing_key = SigningKey::from_bytes(&okm);
    okm.zeroize();
    let verifying_key = signing_key.verifying_key();

    let private_key = Zeroizing::new(signing_key.to_bytes().to_vec());
    let public_key = verifying_key.to_bytes().to_vec();

    // 3. Derive IPNS name from public key
    let pk_array: [u8; 32] = verifying_key.to_bytes();
    let ipns_name = ipns_name::derive_ipns_name(&pk_array)
        .map_err(|_| CryptoError::IpnsNameDerivationFailed)?;

    Ok((private_key, public_key, ipns_name))
}

/// Derive the deterministic Ed25519 IPNS keypair for the user's vault.
///
/// Uses HKDF info "cipherbox-vault-ipns-v1" for domain separation.
///
/// Given the same secp256k1 privateKey, this always produces the same
/// IPNS name, enabling vault discovery from any device with the user's key.
///
/// Returns (ed25519_private_key, ed25519_public_key, ipns_name).
pub fn derive_vault_ipns_keypair(
    user_private_key: &[u8; 32],
) -> Result<(Zeroizing<Vec<u8>>, Vec<u8>, String), CryptoError> {
    derive_ipns_keypair(user_private_key, VAULT_HKDF_INFO)
}

/// Derive a dedicated Ed25519 IPNS keypair for the vault key blob.
///
/// This IPNS name stores the v2 blob containing the ECIES-wrapped rootFolderKey.
/// Separate from the root folder IPNS name to avoid folder publishes overwriting the key blob.
///
/// Uses HKDF info "cipherbox-vault-key-ipns-v1" for domain separation.
pub fn derive_vault_key_ipns_keypair(
    user_private_key: &[u8; 32],
) -> Result<(Zeroizing<Vec<u8>>, Vec<u8>, String), CryptoError> {
    derive_ipns_keypair(user_private_key, VAULT_KEY_HKDF_INFO)
}

/// Derive a deterministic Ed25519 IPNS keypair for a specific file.
///
/// Uses HKDF info "cipherbox-file-ipns-v1:{fileId}" for per-file domain separation.
///
/// Returns (ed25519_private_key, ed25519_public_key, ipns_name).
pub fn derive_file_ipns_keypair(
    user_private_key: &[u8; 32],
    file_id: &str,
) -> Result<(Zeroizing<Vec<u8>>, Vec<u8>, String), CryptoError> {
    if file_id.len() < MIN_FILE_ID_LENGTH {
        return Err(CryptoError::InvalidFileId);
    }

    let info = format!("{}{}", FILE_HKDF_INFO_PREFIX, file_id);
    derive_ipns_keypair(user_private_key, info.as_bytes())
}

/// Derive the deterministic Ed25519 IPNS keypair for the device registry.
///
/// Uses HKDF info "cipherbox-device-registry-ipns-v1" for domain separation.
///
/// Returns (ed25519_private_key, ed25519_public_key, ipns_name).
pub fn derive_registry_ipns_keypair(
    user_private_key: &[u8; 32],
) -> Result<(Zeroizing<Vec<u8>>, Vec<u8>, String), CryptoError> {
    derive_ipns_keypair(user_private_key, REGISTRY_HKDF_INFO)
}

/// Derive the deterministic Ed25519 IPNS keypair for the recycle bin.
///
/// Uses HKDF info "cipherbox-recycle-bin-ipns-v1" for domain separation.
///
/// Returns (ed25519_private_key, ed25519_public_key, ipns_name).
pub fn derive_bin_ipns_keypair(
    user_private_key: &[u8; 32],
) -> Result<(Zeroizing<Vec<u8>>, Vec<u8>, String), CryptoError> {
    derive_ipns_keypair(user_private_key, BIN_HKDF_INFO)
}

