 3→/// Extract the user ID (`sub` claim) from a JWT access token.
 4→///
 5→/// Decodes the JWT payload (base64url) without verification -- the server
 6→/// already verified the token, we just need the `sub` field for Keychain lookup.
 7→pub(crate) fn extract_user_id_from_jwt(token: &str) -> Result<String, String> {
 8→    let parts: Vec<&str> = token.split('.').collect();
 9→    if parts.len() != 3 {
10→        return Err("Invalid JWT format".to_string());
11→    }
12→
13→    // Decode the payload (second part) -- base64url encoding
14→    let payload = parts[1];
15→    // base64url: replace - with + and _ with /, then add padding
16→    let padded = match payload.len() % 4 {
17→        2 => format!("{}==", payload),
18→        3 => format!("{}=", payload),
19→        _ => payload.to_string(),
20→    };
21→    let standard = padded.replace('-', "+").replace('_', "/");
22→
23→    let decoded = base64::Engine::decode(&base64::engine::general_purpose::STANDARD, &standard)
24→        .map_err(|e| format!("Failed to decode JWT payload: {}", e))?;
25→
26→    let json: serde_json::Value = serde_json::from_slice(&decoded)
27→        .map_err(|e| format!("Failed to parse JWT payload: {}", e))?;
28→
29→    json["sub"]
30→        .as_str()
31→        .map(|s| s.to_string())
32→        .ok_or_else(|| "JWT payload missing 'sub' claim".to_string())
